INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('end_to_end_pipeline_data_roh_output_berichte_i', 'cli', 'ja', 'エンドツーエンドのパイプライン: data_raw -> Output_reports を 1 回の呼び出しで実行します。

