INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('liest_inhalte_aus_einem_anonymisierten_bundle_verz', 'cli', 'de', 'Liest Inhalte aus einem anonymisierten Bundle-Verzeichnis.

