INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('memory_handler_db_basiertes_memory_management', 'cli', 'ru', 'Обработчик памяти — управление памятью на основе БД
