INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('merged_remote_backup_in_lokale_db_mit_timestamp_ba', 'cli', 'ja', 'タイムスタンプベースの戦略を使用してローカル DB にリモートバックアップをマージしました。

