INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('partner_handler_partner_verwaltung', 'cli', 'de', 'Partner Handler - Partner-Verwaltung
====================================

--partner list            Alle Partner auflisten
--partner status          Status aller Partner
--partner info <n>        Partner-Details
--partner active          Nur aktive Partner
--partner delegate <task> Task an Partner delegieren (Token-aware)
    --to=NAME             Spezifischer Partner
    --zone=N              Zone erzwingen (1-4)
    --fallback-local, --fal  Bei Offline-Status auf lokale AI (Ollama) ausweichen', 0, 'auto_detected', '2026-02-02T03:35:38.882608', NULL);
INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('partner_handler_partner_verwaltung', 'cli', 'en', 'Partner Handler - Partner Management
====================================

--partner list            List all partners
--partner status          Status of all partners
--partner info <n>        Partner details
