INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('prueft_ob_ein_bridge_daemon_bereits_auf_diesem_pc', 'cli', 'de', 'Prueft ob ein Bridge-Daemon bereits auf diesem PC laeuft (nicht von uns gestartet).

