INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('richtet_gmail_api_zugang_ein_sucht_autom', 'cli', 'ru', 'Настраивает доступ к API Gmail.

