INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('ruft_e_mails_via_gmail_api_ab_mit_serverseitigem_f', 'cli', 'en', 'Fetches emails via Gmail API with SERVER-SIDE filtering.

