INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('select_lower_category_as_cat_count_as_cnt', 'cli', 'de', 'SELECT LOWER(category) as cat, COUNT(*) as cnt 
                FROM tasks 
                WHERE status IN (''pending'', ''open'', ''in_progress'')
                AND LOWER(category) NOT IN (''user'', ''bach'', ''system'', ''gui'', ''wiki'', ''agents'', ''core'', ''mail'', ''integ'', ''ollama'', ''task'', ''deprecate'')
                AND category IS NOT NULL
                AND category != ''''
                GROUP BY LOWER(category)
                HAVING cnt > 1
                ORDER BY cnt DESC', 0, 'auto_detected', '2026-02-02T03:35:38.879923', NULL);
