INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('startet_sofort_eine_claude_session_mit_dem_prompt', 'cli', 'ru', 'Немедленно запускает сеанс Claude с помощью приглашения.

