INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('task_abhaengigkeit_setzen_anzeigen', 'cli', 'de', 'Task-Abhaengigkeit setzen/anzeigen
        
        Usage:
          bach task depends <id>              Abhaengigkeiten anzeigen
          bach task depends <id> --on <id2>   Abhaengigkeit hinzufuegen
          bach task depends <id> --remove <id2>  Abhaengigkeit entfernen
          bach task depends <id> --clear      Alle Abhaengigkeiten loeschen', 0, 'auto_detected', '2026-02-02T03:35:38.881016', NULL);
INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('task_abhaengigkeit_setzen_anzeigen', 'cli', 'en', 'Set/show task dependency
        
        Usage:
          bach task depends <id>              Show dependencies
          bach task depends <id> --on <id2>   Add dependency
          bach task depends <id> --remove <id2>  Remove dependency
          bach task depends <id> --clear      Clear all dependencies', 0, 'waterfall_swarm', '2026-03-06 19:52:54', '2026-03-06 19:52:54');
INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('task_abhaengigkeit_setzen_anzeigen', 'cli', 'es', 'Establecer/mostrar dependencia de tareas
        
        Uso:
          la tarea de bach depende <id> Mostrar dependencias
          la tarea de bach depende <id> --on <id2> Agregar dependencia
          la tarea de bach depende <id> --remove <id2> Eliminar dependencia
          la tarea de bach depende <id> --clear Borrar todas las dependencias', 0, 'google_auto', '2026-05-17T06:08:46.131662', '2026-05-17T06:08:46.131662');
INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('task_abhaengigkeit_setzen_anzeigen', 'cli', 'ja', 'タスクの依存関係を設定/表示する
        
        使用法:
          Bach タスクの依存関係 <id> 依存関係の表示
          bach タスクは <id> --on <id2> に依存します 依存関係を追加します
          bach タスクは <id> に依存します --remove <id2> 依存関係を削除します
          bach タスクは <id> に依存します --clear すべての依存関係をクリアします', 0, 'google_auto', '2026-05-17T06:33:13.916677', '2026-05-17T06:33:13.916677');
INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('task_abhaengigkeit_setzen_anzeigen', 'cli', 'ru', 'Установить/показать зависимость задачи
        
        Использование:
          Задача Баха зависит <id> Показать зависимости
          Задача Бача зависит от <id> --on <id2> Добавить зависимость
          Задача bach зависит от <id> --remove <id2> Удалить зависимость
          Задача bach зависит от <id> --clear Очистить все зависимости', 0, 'google_auto', '2026-05-17T06:24:37.729914', '2026-05-17T06:24:37.729914');
INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('task_abhaengigkeit_setzen_anzeigen', 'cli', 'zh', '设置/显示任务依赖性
        
        用途：
          bach 任务依赖 <id> 显示依赖关系
          bach 任务取决于 <id> --on <id2> 添加依赖项
          bach 任务依赖 <id> --remove <id2> 删除依赖
          bach 任务依赖 <id> --clear 清除所有依赖项', 0, 'google_auto', '2026-05-17T06:40:24.434869', '2026-05-17T06:40:24.434869');
