INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('verwaltet_db_backups_und_prosync_zwischen_systemen', 'cli', 'es', 'Verwaltet DB-Backups y ProSync dos sistemas.

