INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('args_callback_funktion_event_type_f', 'gui', 'en', 'Args:
            callback: Function(event_type, file_path, file_type) called on change
            watched_extensions: Set of file extensions (e.g. {''.db'', ''.txt'', ''.json''})
            debounce_seconds: Wait time for debouncing (prevents duplicate events)', 0, 'waterfall_swarm', '2026-03-06 19:52:09', '2026-03-06 19:52:09');
INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('args_callback_funktion_event_type_f', 'gui', 'es', 'Argumentos:
            devolución de llamada: Función (tipo_evento, ruta_archivo, tipo_archivo) llamada en caso de cambio
            watch_extensions: conjunto de extensiones de archivo (por ejemplo, {''.db'', ''.txt'', ''.json''})
            debounce_segundos: tiempo de espera para eliminar rebotes (evita eventos duplicados)', 0, 'google_auto', '2026-05-17T05:57:01.217417', '2026-05-17T05:57:01.217417');
INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('args_callback_funktion_event_type_f', 'gui', 'ja', '引数:
            コールバック: 変更時に呼び出される関数(event_type, file_path, file_type)
            Watched_extensions: ファイル拡張子のセット (例: {''.db''、''.txt''、''.json''})
            debounce_seconds: デバウンスの待機時間 (イベントの重複を防止します)', 0, 'google_auto', '2026-05-17T06:33:13.916677', '2026-05-17T06:33:13.916677');
INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('args_callback_funktion_event_type_f', 'gui', 'ru', 'Аргументы:
            обратный вызов: функция (тип_события, путь_файла, тип_файла), вызываемая при изменении
            наблюдаемые_расширения: набор расширений файлов (например, {''.db'', ''.txt'', ''.json''}).
            debounce_секунды: время ожидания устранения дребезга (предотвращает дублирование событий)', 0, 'google_auto', '2026-05-17T06:24:37.729914', '2026-05-17T06:24:37.729914');
INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('args_callback_funktion_event_type_f', 'gui', 'zh', '参数：
            回调：函数（event_type，file_path，file_type）在更改时调用
            watch_extensions：文件扩展名集（例如 {''.db'', ''.txt'', ''.json''}）
            debounce_seconds：去抖动的等待时间（防止重复事件）', 0, 'google_auto', '2026-05-17T06:40:24.434869', '2026-05-17T06:40:24.434869');
