                COUNT(*) как дубликаты,
                GROUP_CONCAT(id) как дубликаты_идентификаторов
            ИЗ v_subscriptions
            ГДЕ статус = «активный»
            GROUP BY LOWER(имя), LOWER(COALESCE(поставщик, ''''))
            СОРТИРОВАТЬ ПО ежемесячной стоимости DESC', 0, 'google_auto', '2026-05-17T06:24:37.729914', '2026-05-17T06:24:37.729914');
INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('select_name_provider_category_m', 'gui', 'zh', '选择
