INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('agent_launcher', 'help_doc', 'ja', '# Portability: UNIVERSAL
# Last validated: 2026-05-17
