INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('cli', 'help_doc', 'de', '# Portabilität: UNIVERSAL
# Zuletzt validiert: 2026-03-04 (Root-Docs-Review)
