INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('meta_feedback_injector', 'help_doc', 'en', '# Portability: UNIVERSAL
# Last validated: 2026-05-17
