  # すべてのパートナーを認識する
  パートナー = manager.detect_active_partners()
  print(パートナー) # ["クロードコード"]

  # BACHを登録する
  成功、msg = manager.register_partner("claude-code")
  print(msg) # ✓ CLAUDE.md が作成されました: ~/.CLAUDE.md

  #全員登録
  results = manager.register_all_detected()


