INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('tools/rag', 'help_doc', 'ru', 'Инструмент BACH: RAG (Поисковая расширенная генерация)
------------------------------------------------

Векторный поиск документов для BACH.

