INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('baut_den_vollstaendigen_llm_prompt_zusammen', 'skills', 'de', 'Baut den vollstaendigen LLM-Prompt zusammen.

    Der Prompt instruiert das LLM:
    - Beobachtungen zu analysieren
    - Relevante ICF-Bereiche zu identifizieren
    - Strukturierten JSON-Output zu generieren', 0, 'auto_detected', '2026-02-02T03:38:35.221245', NULL);
INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('baut_den_vollstaendigen_llm_prompt_zusammen', 'skills', 'en', 'Builds the complete LLM prompt.

    The prompt instructs the LLM to:
    - Analyze observations
    - Identify relevant ICF domains
    - Generate structured JSON output', 0, 'waterfall_swarm', '2026-03-06 19:53:26', '2026-03-06 19:53:26');
INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('baut_den_vollstaendigen_llm_prompt_zusammen', 'skills', 'es', 'Crea el mensaje LLM completo.

